// Parse SQL dan extract CREATE TABLE statements
const sqlInput = $input.first().json.body.sql || '';

// Regex untuk extract CREATE TABLE
const tablePattern = /CREATE\s+TABLE\s+(?:public\.)?"?(\w+)"?\s*\(([\s\S]*?)\)(?:\s*;)?/gi;

const tables = [];
let match;

while ((match = tablePattern.exec(sqlInput)) !== null) {
  const tableName = match[1];
  const tableBody = match[2];

  // Parse columns
  const columns = [];
  const lines = tableBody.split(',');

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.toUpperCase().startsWith('CONSTRAINT') || trimmed.toUpperCase().startsWith('PRIMARY') || trimmed.toUpperCase().startsWith('FOREIGN')) {
      continue;
    }

    // Match column: name type [constraints]
    const colMatch = trimmed.match(/^"?(\w+)"?\s+(\w+(?:\([^)]+\))?)/);
    if (colMatch) {
      columns.push({
        name: colMatch[1],
        type: colMatch[2]
      });
    }
  }

  tables.push({
    name: tableName,
    columns: columns,
    definition: match[0]
  });
}

return [{ json: { tables, sqlInput } }];

