// Collect all results dan format sebagai dokumentasi
const items = $input.all();
const allDocs = [];

for (const item of items) {
  try {
    const tableName = item.json.tables?.[0]?.name || 'Unknown';
    const columns = item.json.tables?.[0]?.columns || [];
    const definition = item.json.tables?.[0]?.definition || '';

    // Parse AI response
    let aiResponse = item.json.message?.content || '{}';
    let aiDoc = {};

    try {
      const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        aiDoc = JSON.parse(jsonMatch[0]);
      }
    } catch (e) {
      aiDoc = { table_description: 'Dokumentasi otomatis', columns: {} };
    }

    allDocs.push({
      table_name: tableName,
      description: aiDoc.table_description || 'Dokumentasi belum tersedia',
      columns: columns.map((col, idx) => ({
        no: idx + 1,
        name: col.name,
        type: col.type,
        description: aiDoc.columns?.[col.name] || `Field ${col.name}`
      })),
      sql_definition: definition
    });
  } catch (e) {
    // Skip errors
  }
}

return [{ json: { documentation: allDocs, total_tables: allDocs.length } }];

// Generate Markdown output
const docs = $input.first().json.documentation;
const total = $input.first().json.total_tables;

let markdown = `# 📚 Dokumentasi Database Schema\n\n`;
markdown += `> **Generated:** ${new Date().toISOString()}\n`;
markdown += `> **Total Tables:** ${total}\n\n`;
markdown += `---\n\n`;

// Daftar Tables
markdown += `## 📋 Daftar Tables\n\n`;
markdown += `| No | Nama Table | Deskripsi |\n`;
markdown += `|----|------------|-----------|\n`;

docs.forEach((doc, idx) => {
  markdown += `| ${idx + 1} | \`${doc.table_name}\` | ${doc.description} |\n`;
});

markdown += `\n---\n\n`;

// Detail per table
docs.forEach((doc, idx) => {
  markdown += `## ${idx + 1}. \`${doc.table_name}\`\n\n`;
  markdown += `### Deskripsi\n${doc.description}\n\n`;
  markdown += `### Kolom\n\n`;
  markdown += `| No | Nama Field | Tipe Data | Deskripsi |\n`;
  markdown += `|----|------------|-----------|-----------|\n`;

  doc.columns.forEach(col => {
    markdown += `| ${col.no} | ${col.name} | ${col.type} | ${col.description} |\n`;
  });

  markdown += `\n<details>\n<summary>📝 <strong>SQL Definition</strong></summary>\n\n`;
  markdown += `\`\`\`sql\n${doc.sql_definition}\n\`\`\`\n\n</details>\n\n`;
  markdown += `---\n\n`;
});

return [{ 
  json: { 
    markdown: markdown,
    documentation: docs,
    total_tables: total 
  } 
}];
